import{_ as o,o as t,c as r,a2 as a}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"设计模式手册：从 DSH 提炼的可迁移模式","description":"","frontmatter":{},"headers":[],"relativePath":"interview/patterns.md","filePath":"interview/patterns.md","lastUpdated":null}'),s={name:"interview/patterns.md"};function n(d,e,i,l,c,g){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="设计模式手册-从-dsh-提炼的可迁移模式" tabindex="-1">设计模式手册：从 DSH 提炼的可迁移模式 <a class="header-anchor" href="#设计模式手册-从-dsh-提炼的可迁移模式" aria-label="Permalink to &quot;设计模式手册：从 DSH 提炼的可迁移模式&quot;">​</a></h1><blockquote><p>面试官问&quot;研究 DSH 学到了什么&quot;时，最好的回答是<strong>能迁移的设计模式</strong>。这 12 个模式每一条都能脱离 DSH 用在其他 agent/后端/前端项目里。每条格式：模式 → 解决的问题 → 做法 → 代价 → 面试话术。</p></blockquote><h2 id="_1-事件溯源会话日志-event-sourced-session-log" tabindex="-1">1. 事件溯源会话日志（Event-Sourced Session Log） <a class="header-anchor" href="#_1-事件溯源会话日志-event-sourced-session-log" aria-label="Permalink to &quot;1. 事件溯源会话日志（Event-Sourced Session Log）&quot;">​</a></h2><p><strong>问题</strong>：agent 的对话历史、UI 回放、fork、恢复、遥测各需要一份数据，维护多份状态必然漂移。</p><p><strong>做法</strong>：append-only 事件日志是唯一真源；所有派生视图（模型历史 <code>deriveMessages</code>、UI 快照、计量、标题）都是日志的纯函数折叠。修改被建模为&quot;追加 + 遮蔽&quot;（<code>surfaceOp: replace</code>），日志永不删除。</p><p><strong>代价</strong>：日志体积膨胀；折叠逻辑要正确处理&quot;位置替换&quot;（<code>shadowedRange</code> 是位置跨度而非数值区间）。</p><p><strong>话术</strong>：&quot;DSH 的会话日志是事件溯源：模型历史是从 <code>SessionEvent</code> 日志投影出来的视图，而不是独立维护的消息数组。&#39;模型可见即已记录&#39;是一条运行时不变量——任何到达模型请求的内容都能从日志重建。这解决了审计、崩溃恢复、fork 的一致性三难题。&quot;</p><h2 id="_2-能力-seam-capability-seam" tabindex="-1">2. 能力 Seam（Capability Seam） <a class="header-anchor" href="#_2-能力-seam-capability-seam" aria-label="Permalink to &quot;2. 能力 Seam（Capability Seam）&quot;">​</a></h2><p><strong>问题</strong>：可替换能力（LLM、文件系统、沙箱、子代理）如何做到&quot;换实现不换接口、消费方零改动&quot;？</p><p><strong>做法</strong>：每个能力 = Service Definition（抽象类 + 词汇类型，拥有 <code>ctx.&lt;key&gt;</code>）+ 多个 Provider（可替换实现）+ Consumer（面向模型工具）。<strong>单一角色不是 seam</strong>。</p><p><strong>代价</strong>：包数量多、层级深；要防止&quot;一个 Consumer 说了算的服务契约&quot;（逆味）。</p><p><strong>话术</strong>：&quot;DSH 把每个能力拆成三角色。文件系统和进程提供方共享同一个执行世界，所以把两者指向远程沙箱，Bash、PTY、LSP 全部跟着搬过去，没有任何提供方专用 fork。这是依赖倒置在 agent 运行时上的完整落地。&quot;</p><h2 id="_3-可扩展瀑布-单调守卫-waterfall-monotonic-guard" tabindex="-1">3. 可扩展瀑布 + 单调守卫（Waterfall + Monotonic Guard） <a class="header-anchor" href="#_3-可扩展瀑布-单调守卫-waterfall-monotonic-guard" aria-label="Permalink to &quot;3. 可扩展瀑布 + 单调守卫（Waterfall + Monotonic Guard）&quot;">​</a></h2><p><strong>问题</strong>：策略拦截既要&quot;可组合、可询问用户&quot;（审批），又要&quot;不可绕过&quot;（安全规则）。一套机制做不到两者。</p><p><strong>做法</strong>：双轨。<code>tools/pre-execute</code> waterfall 允许 allow/deny/ask 且顺序敏感；<code>ToolGuard</code> 只能返回拒绝 reason，<strong>没有 allow 分支</strong>，顺序无法翻案。owner 策略（沙箱模式检查）放守卫。</p><p><strong>话术</strong>：&quot;DSH 把&#39;可扩展&#39;与&#39;不可撤销&#39;拆成两条轨道：瀑布式监听器可以做任意决策甚至询问用户，但顺序敏感；单调守卫只能拒绝，注册后顺序无法把拒绝翻回放行。安全策略走守卫，产品策略走瀑布。&quot;</p><h2 id="_4-中间件化的-agent-loop-loop-as-event-middleware" tabindex="-1">4. 中间件化的 Agent Loop（Loop as Event Middleware） <a class="header-anchor" href="#_4-中间件化的-agent-loop-loop-as-event-middleware" aria-label="Permalink to &quot;4. 中间件化的 Agent Loop（Loop as Event Middleware）&quot;">​</a></h2><p><strong>问题</strong>：agent 循环里的每一步（请求构造、流式输出、工具执行、轮次停止）都需要被观测/拦截，但不能硬编码策略。</p><p><strong>做法</strong>：循环只做状态机（turn/step/inbox），所有决策点都是 waterfall 事件：<code>agent/pre-step</code>（决定模型看到什么）、<code>agent/request</code>（改写请求）、<code>llm/stream</code>（包装流）、<code>tools/*</code>（策略三段）、<code>agent/turn-stopping</code>（终止检查点）。<strong>压缩、审批、沙箱、遥测全部是监听器，不是循环代码</strong>。</p><p><strong>话术</strong>：&quot;DSH 的循环本身没有特权：它只是把输入排空的状态机，每个决策点都发出 waterfall 事件。压缩挂在 pre-step、审批挂在 tools/pre-execute、超时包装 tools/execute——策略即插件，加新策略不改循环。&quot;</p><h2 id="_5-模型可见-⟺-已记录-model-visible-⟺-logged" tabindex="-1">5. 模型可见 ⟺ 已记录（Model-Visible ⟺ Logged） <a class="header-anchor" href="#_5-模型可见-⟺-已记录-model-visible-⟺-logged" aria-label="Permalink to &quot;5. 模型可见 ⟺ 已记录（Model-Visible ⟺ Logged）&quot;">​</a></h2><p><strong>问题</strong>：agent 审计的最强形式是什么？答案是&quot;请求可以被日志重建&quot;。</p><p><strong>做法</strong>：新增模型可见输入必须新增会话事件；<code>request/header</code> 快照 system+tools+config；<code>assistant/chunk</code> 逐分片入库；<strong>运行时不变量重算等式</strong>（请求的 messages 必须等于 <code>deriveMessages()</code>）。</p><p><strong>话术</strong>：&quot;DSH 把&#39;可审计&#39;做成机器可证的：<code>llm/stream</code> 上的运行时不变量重算&#39;请求 = 日志纯函数&#39;。新增模型可见输入而不加日志事件，构建就失败。这在金融级 agent 场景就是审计合规的基础。&quot;</p><h2 id="_6-先剪枝后摘要-deterministic-first-cost-ladder" tabindex="-1">6. 先剪枝后摘要（Deterministic-First Cost Ladder） <a class="header-anchor" href="#_6-先剪枝后摘要-deterministic-first-cost-ladder" aria-label="Permalink to &quot;6. 先剪枝后摘要（Deterministic-First Cost Ladder）&quot;">​</a></h2><p><strong>问题</strong>：上下文超限时的恢复路径，模型调用（摘要）可能失败，怎么办？</p><p><strong>做法</strong>：成本阶梯。计量（启发式，零成本）→ 剪枝（确定性、无模型调用、&quot;必赢&quot;）→ 摘要（模型调用，可能失败）→ spill（溢出到文件）。<strong>先落地必赢的缩减，再让模型处理剩余</strong>。恢复是否有进展用 <code>replaceGeneration</code> 是否前进判断——日志状态而非内存状态。</p><p><strong>话术</strong>：&quot;DSH 的压缩是阶梯式的：超限先做模型无关的工具结果剪枝（保首尾、换中段），重测仍超才调模型摘要。因为剪枝是确定性的，即使摘要失败，恢复也已经有了持久进展——<code>agent/request-error</code> 靠 surface 替换代数是否前进决定要不要重试。&quot;</p><h2 id="_7-日志事件即锁-log-events-as-locks" tabindex="-1">7. 日志事件即锁（Log Events as Locks） <a class="header-anchor" href="#_7-日志事件即锁-log-events-as-locks" aria-label="Permalink to &quot;7. 日志事件即锁（Log Events as Locks）&quot;">​</a></h2><p><strong>问题</strong>：分布式/崩溃场景下，并发互斥的锁放在内存里会怎样？崩溃后死锁。</p><p><strong>做法</strong>：<code>compaction/start</code>…<code>compaction/end</code> 配对就是锁。&quot;有 start 无 end&quot; = 崩溃遗留锁 → 后续入口拒绝（busy）；旧生命周期的遗留 start 按 <code>end-seed</code> 边界识别为残留。<strong>并发协议也记录在日志里</strong>。</p><p><strong>话术</strong>：&quot;DSH 的压缩互斥不靠内存标志，靠日志事件配对。崩溃留下的&#39;有 start 无 end&#39;可检测，这是事件溯源顺理成章的延伸——协议即日志。&quot;</p><h2 id="_8-有界委托-受限脚本-bounded-delegation" tabindex="-1">8. 有界委托 + 受限脚本（Bounded Delegation） <a class="header-anchor" href="#_8-有界委托-受限脚本-bounded-delegation" aria-label="Permalink to &quot;8. 有界委托 + 受限脚本（Bounded Delegation）&quot;">​</a></h2><p><strong>问题</strong>：模型生成代码（workflow 脚本）怎么跑才安全？</p><p><strong>做法</strong>：<strong>containment 而非 security</strong>——worker 线程（防同步阻塞、可 force-terminate）+ vm 上下文只注入 6 个钩子（无 fs/网络/timer）+ 值离 realm 必物化纯 JSON + fatal 判定用宿主 realm <code>instanceof</code>（脚本伪造不了）。<strong>信任边界在进程/线程边界，不依赖模型代码的善意</strong>。</p><p><strong>话术</strong>：&quot;DSH 的 workflow 引擎让模型写 JS 编排脚本，但脚本跑在 worker 线程的受限 vm 里，只有 agent/pipeline/parallel 等六个钩子。&#39;代理干活，脚本只编排&#39;——信任边界放在线程边界，模型代码崩溃也崩不坏宿主。&quot;</p><h2 id="_9-失败的类型化-failures-as-discriminated-unions" tabindex="-1">9. 失败的类型化（Failures as Discriminated Unions） <a class="header-anchor" href="#_9-失败的类型化-failures-as-discriminated-unions" aria-label="Permalink to &quot;9. 失败的类型化（Failures as Discriminated Unions）&quot;">​</a></h2><p><strong>问题</strong>：agent 系统的失败有几十种，字符串错误码 + try/catch 会失控。</p><p><strong>做法</strong>：失败是判别联合。<code>SubagentResult.stopReason</code>、<code>ToolExecutionResult {isError, error:{name, code}}</code>、<code>WorkflowResult.stopReason</code>、<code>LlmFailure.code</code> 稳定机器路由码。消费方 switch 已知分支、default 按失败处理。<strong>把失败做成类型系统可表达的联合</strong>。</p><p><strong>话术</strong>：&quot;DSH 把失败建模成判别联合而不是异常流：工具结果是 <code>isError</code> 布尔 + 结构化 error code 的联合，workflow 的 fatal 与逐项 null 用类型区分。消费方穷尽分支、未知变体默认失败——AI 系统的错误处理应该向编译器借力。&quot;</p><h2 id="_10-作用域化注册-scoped-registration" tabindex="-1">10. 作用域化注册（Scoped Registration） <a class="header-anchor" href="#_10-作用域化注册-scoped-registration" aria-label="Permalink to &quot;10. 作用域化注册（Scoped Registration）&quot;">​</a></h2><p><strong>问题</strong>：多个 agent（含子代理）共用一个进程，工具/提示词/监听器怎么隔离？</p><p><strong>做法</strong>：两层扁平作用域：全局 or 属于恰好一个 scope key（活跃 agent 即自身 scope 的 key）。scoped 注册遮蔽全局同名；restriction 只过滤继承面，<strong>本 scope 自己的注册不受限</strong>（子代理保留回报工具）。<strong>不向下继承</strong>——子树行为用 lineage 数据表达。</p><p><strong>话术</strong>：&quot;DSH 的工具注册表按 agent 作用域分层：子代理默认看不到父代理的作用域注册，但父的 restriction 过滤不了子自己的注册——所以子代理总能保留自己的回报工具。shadowing 机制让同名工具可以在不同 agent 上有不同变体。&quot;</p><h2 id="_11-凭据只存引用-credentials-as-references" tabindex="-1">11. 凭据只存引用（Credentials as References） <a class="header-anchor" href="#_11-凭据只存引用-credentials-as-references" aria-label="Permalink to &quot;11. 凭据只存引用（Credentials as References）&quot;">​</a></h2><p><strong>问题</strong>：密钥如何做到热轮换、不进日志/模型上下文、不被误持久化？</p><p><strong>做法</strong>：配置里只有环境变量名（<code>CredentialRef</code>）；<strong>每次操作重新解析</strong>；key 只出现在传输层 header；错误只点名 ref 不回显值；遮蔽可拒绝（写会被环境遮蔽时直接报错）。</p><p><strong>话术</strong>：&quot;DSH 的凭据系统只存引用不存值：配置和 cordis.yml 里是环境变量名，适配器在传输层才解析。热轮换、密钥与模型上下文物理隔离、&#39;表面写入成功但被环境遮蔽&#39;直接拒绝——三条纪律一条不少。&quot;</p><h2 id="_12-组合优于继承的构建面-faces-over-monoliths" tabindex="-1">12. 组合优于继承的构建面（Faces over Monoliths） <a class="header-anchor" href="#_12-组合优于继承的构建面-faces-over-monoliths" aria-label="Permalink to &quot;12. 组合优于继承的构建面（Faces over Monoliths）&quot;">​</a></h2><p><strong>问题</strong>：同一批代码要给 Node 与浏览器两个运行时，怎么组织构建？</p><p><strong>做法</strong>：host/client 双编译面；tsc 项目引用产出中间产物，tsdown 按 workspace 打包；类型图（Typert）在构建期生成，供 RPC 网关运行时反射。<strong>源面与产物面从不混用</strong>。</p><p><strong>话术</strong>：&quot;DSH 的 monorepo 用双编译面解决 Node/浏览器同构：同一批 client 包产两份工件，RPC 描述符由 Typert 在构建期从 TS Program 生成——类型安全在构建期验证，运行时只有描述符解析。&quot;</p><hr><h2 id="附-dsh-与-claude-code-的架构差异-研究笔记提炼" tabindex="-1">附：DSH 与 Claude Code 的架构差异（研究笔记提炼） <a class="header-anchor" href="#附-dsh-与-claude-code-的架构差异-研究笔记提炼" aria-label="Permalink to &quot;附：DSH 与 Claude Code 的架构差异（研究笔记提炼）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>DSH</th><th>Claude Code</th></tr></thead><tbody><tr><td>会话真源</td><td>append-only <code>SessionEvent</code> 日志，模型历史是投影</td><td>消息数组（JSONL 持久化）</td></tr><tr><td>扩展点</td><td>类型化 Cordis 事件（waterfall/serial/emit）+ seam</td><td>hooks + MCP + skills</td></tr><tr><td>工具策略</td><td>pre/guard/around/post 四段 + 单调守卫</td><td>权限规则 + hooks</td></tr><tr><td>循环</td><td>可替换插件（<code>agent-loop</code> 是默认实现）</td><td>固化循环 + hooks 拦截</td></tr><tr><td>前端</td><td>插件化浏览器 Cordis（slot 系统）</td><td>相对单体 React 应用</td></tr><tr><td>多代理</td><td>命名 Provider 注册表（进程内/ACP/Codex）</td><td>task 工具 + subagent</td></tr></tbody></table><p>下一篇：<a href="/interview/qa">高频面试题</a>——50+ 题带答案要点。</p>',56)])])}const h=o(s,[["render",n]]);export{u as __pageData,h as default};
